import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

/**
 * Asia Pacific Airport Simulation
 * High-performance concurrency model using Semaphores and specialized Task-Threads.
 */
public class AsiaPacificAirport {
    // SEMAPHORES for resource management
    private final Semaphore runway = new Semaphore(1, true); // Exclusive runway
    private final Semaphore groundCapacity = new Semaphore(3, true); // Max 3 planes on ground
    private final Semaphore gates = new Semaphore(3, true); // 3 gate locations
    private final Semaphore fuelTruck = new Semaphore(1, true); // 1 exclusive fuel truck

    // METRICS for Sanity Checks/Stats
    private final AtomicInteger planesServed = new AtomicInteger(0);
    private final LongAdder totalWaitTime = new LongAdder();
    private final long startTime = System.currentTimeMillis();

    class Airplane implements Runnable {
        private final int id;
        private final boolean isEmergency;
        private long requestTime;

        Airplane(int id, boolean isEmergency) {
            this.id = id;
            this.isEmergency = isEmergency;
        }

        @Override
        public void run() {
            try {
                requestTime = System.currentTimeMillis();
                System.out.printf("[REQUEST] Plane %d %s is requesting to land.\n", id, isEmergency ? "***EMERGENCY***" : "");

                // 1. GROUND ENTRY (Capacity check)
                groundCapacity.acquire();

                // 2. RUNWAY LANDING
                runway.acquire();
                System.out.printf("[LANDING] Plane %d on runway. (Current Grounds: %d)\n", id, 4 - groundCapacity.availablePermits());
                Thread.sleep(500); // Time to land
                runway.release();

                // 3. DOCKING
                gates.acquire();
                System.out.printf("[DOCKED] Plane %d at Gate. Starting services.\n", id);

                // 4. CONCURRENT SERVICING (Requirement: Concurrent disembark/cleaning, Exclusive refuelling)
                CountDownLatch services = new CountDownLatch(3);

                // Thread 1: Passengers (Disembark/Embark)
                new Thread(() -> { performTask("Passengers", 1000); services.countDown(); }).start();
                // Thread 2: Cleaning
                new Thread(() -> { performTask("Cleaning", 800); services.countDown(); }).start();
                // Thread 3: Refuelling (Exclusive resource truck)
                new Thread(() -> {
                    try {
                        fuelTruck.acquire();
                        performTask("Refuelling", 1200);
                        fuelTruck.release();
                        services.countDown();
                    } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
                }).start();

                services.await(); // Wait for all concurrent servicing to finish

                // 5. TAKEOFF
                runway.acquire();
                System.out.printf("[TAKEOFF] Plane %d clearing runway.\n", id);
                Thread.sleep(500);

                // 6. DEPARTURE (Release resources)
                gates.release();
                runway.release();
                groundCapacity.release();

                // Statistics
                planesServed.incrementAndGet();
                totalWaitTime.add(System.currentTimeMillis() - requestTime);
                System.out.printf("[DEPARTED] Plane %d has left the airport.\n", id);

            } catch (InterruptedException e) {
                System.err.println("Plane " + id + " interrupted.");
                Thread.currentThread().interrupt();
            }
        }

        private void performTask(String name, int duration) {
            try { Thread.sleep(duration); } catch (InterruptedException e) { }
        }
    }

    public void simulateCongestedScenario() {
        System.out.println("--- SIMULATION START: CONGESTED SCENARIO ---");
        ExecutorService airportExecutor = Executors.newCachedThreadPool();

        // Step 1: Occupy 2 gates
        airportExecutor.execute(new Airplane(1, false));
        airportExecutor.execute(new Airplane(2, false));

        try { Thread.sleep(200); } catch (InterruptedException e) {}

        // Step 2: 2 planes waiting (3rd spot on ground vs Runway lock)
        airportExecutor.execute(new Airplane(3, false));
        airportExecutor.execute(new Airplane(4, false));

        // Step 3: Emergency landing
        airportExecutor.execute(new Airplane(999, true));

        airportExecutor.shutdown();
        try {
            if (airportExecutor.awaitTermination(30, TimeUnit.SECONDS)) {
                printFinalStats();
            }
        } catch (InterruptedException e) { }
    }

    private void printFinalStats() {
        System.out.println("\n--- AIRPORT STATISTICS ---");
        System.out.println("Total Planes Served: " + planesServed.get());
        System.out.println("Total Ops Time: " + (System.currentTimeMillis() - startTime) + "ms");
        System.out.println("Avg Turnaround Time: " + (totalWaitTime.sum() / planesServed.get()) + "ms");
        System.out.println("--------------------------");
    }

    public static void main(String[] args) {
        new AsiaPacificAirport().simulateCongestedScenario();
    }
}
